package com.example

import com.example.ExamQuestionHelper.QSpec

internal object EnglishLiveExamPartsBank2 {
  private const val T = "Articles, Determiners, Adjectives & Adverbs"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("Choose the correct article: 'Sri Lanka is ___ island in the Indian Ocean.'", "an", "a", "the", "no article", "'Island' begins with a vowel sound, so use 'an'."),
    q("Select the right article: 'My elder brother studies at ___ university in Colombo.'", "a", "an", "the", "no article", "'University' begins with a consonant /j/ sound ('yoo'), so use 'a'."),
    q("Fill in the blank: 'He waited for ___ hour outside the science laboratory.'", "an", "a", "the", "no article", "The 'h' in 'hour' is silent, starting with a vowel sound: 'an hour'."),
    q("Choose the accurate article: 'It was ___ honest mistake on his part.'", "an", "a", "the", "no article", "Silent 'h' in 'honest' gives a vowel sound, requiring 'an'."),
    q("Select the correct article: 'She bought ___ uniform before the new term began.'", "a", "an", "the", "no article", "'Uniform' starts with the /j/ consonant sound, so use 'a'."),
    q("Fill in the blank: '___ European tourist asked us for directions to Temple Street.'", "A", "An", "The", "No article", "'European' starts with a /j/ sound, so indefinite 'A' is used."),
    q("Choose the right article: 'We saw ___ one-eyed pirate in the stage drama.'", "a", "an", "the", "no article", "'One' starts with a /w/ consonant sound ('wun'), so use 'a'."),
    q("Select the correct article: 'Mr. Silva is ___ M.P. representing our district.'", "an", "a", "the", "no article", "The letter 'M' is pronounced /em/, beginning with a vowel sound: 'an M.P.'."),
    q("Fill in the blank: '___ sun rises in the east every morning.'", "The", "A", "An", "No article", "Unique celestial bodies take the definite article 'The'."),
    q("Choose the right article: '___ Mahaweli River flows into the sea near Trincomalee.'", "The", "A", "An", "No article", "Names of rivers take 'The'."),
    q("Select the accurate option: '___ Mount Everest is the highest peak on Earth.'", "No article", "The", "A", "An", "Single mountain peaks do not take 'the' (unlike mountain ranges)."),
    q("Fill in the blank: '___ Himalayas lie along the northern border of India.'", "The", "A", "An", "No article", "Mountain ranges take the definite article 'The'."),
    q("Choose the correct option: 'Our family enjoys playing ___ cricket on weekends.'", "no article", "the", "a", "an", "Names of sports and games take zero article."),
    q("Select the right article: 'They usually have ___ breakfast at seven o'clock.'", "no article", "the", "a", "an", "General meal names take zero article unless modified."),
    q("Fill in the blank: 'Amaya can play ___ piano with great skill.'", "the", "a", "an", "no article", "Playing musical instruments takes 'the' ('play the piano')."),
    q("Choose the accurate article: '___ poor often struggle during severe floods.'", "The", "A", "An", "No article", "'The + adjective' represents an entire group of people."),
    q("Select the right article: '___ richer he grew, the more generous he became.'", "The", "A", "An", "No article", "Double comparatives follow 'The + comparative..., the + comparative...'."),
    q("Fill in the blank: 'Kandy is ___ cultural capital of Sri Lanka.'", "the", "a", "an", "no article", "Unique official titles or roles take 'the'."),
    q("Choose the correct article: 'I bought a pen yesterday; ___ pen writes smoothly.'", "the", "a", "an", "no article", "On second mention of a known item, use 'the'."),
    q("Select the right option: 'Can you speak ___ Tamil fluently?'", "no article", "the", "a", "an", "Language names take zero article when used alone."),
    q("Fill in the blank: '___ English language is spoken across many continents.'", "The", "A", "An", "No article", "When followed by 'language', use 'The English language'."),
    q("Choose the correct determiner: 'How ___ sugar do you take in your tea?'", "much", "many", "few", "several", "Uncountable noun 'sugar' requires 'much'."),
    q("Select the accurate determiner: 'How ___ students participated in the debate?'", "many", "much", "little", "less", "Plural countable noun 'students' takes 'many'."),
    q("Fill in the blank: 'We have very ___ time left before the bell rings.'", "little", "few", "many", "several", "'Little' expresses a small amount with uncountable 'time'."),
    q("Choose the right determiner: 'Only a ___ seats remained empty in the hall.'", "few", "little", "much", "less", "'A few' indicates a small countable number ('seats')."),
    q("Select the best option: 'There is ___ hope of rain today; the sky is clear.'", "little", "a little", "few", "a few", "'Little' (without 'a') means almost none, with uncountable 'hope'."),
    q("Complete positively: 'With ___ practice, you can master English essays.'", "a little", "little", "few", "many", "'A little' means a small positive amount with uncountable nouns."),
    q("Choose the right determiner: 'Have you got ___ spare pens in your pouch?'", "any", "much", "a little", "every", "Questions with plural nouns commonly use 'any'."),
    q("Fill in the blank: 'There isn't ___ milk left in the refrigerator.'", "any", "some", "many", "few", "Negative statements take 'any' with uncountable nouns."),
    q("Select the polite offer form: 'Would you like ___ fresh orange juice?'", "some", "any", "few", "many", "Polite offers and requests use 'some' even in questions."),
    q("Choose the right determiner: '___ candidate must bring an admission card.'", "Every", "All", "Both", "Many", "'Every' pairs with a singular countable noun ('candidate')."),
    q("Fill in the blank: '___ student in the team received a certificate.'", "Each", "All", "Both", "Several", "'Each' emphasizes individuals with singular noun and verb."),
    q("Select the accurate determiner: 'I have read ___ pages of this chapter.'", "several", "much", "every", "each", "'Several' pairs with plural countable nouns ('pages')."),
    q("Choose the correct form: '___ of the two roads leads to the town centre.'", "Either", "All", "Both", "Many", "'Either' matches singular verb 'leads' for two options."),
    q("Fill in the blank: 'There is ___ ink in this bottle than in that one.'", "less", "fewer", "few", "many", "'Less' is the comparative of 'little' for uncountable nouns."),
    q("Select the accurate word: 'This year there are ___ absences than last term.'", "fewer", "less", "little", "much", "'Fewer' is used with plural countable nouns like 'absences'."),
    q("Choose the right determiner: 'We need ___ extra chairs for the parents.'", "a few", "a little", "much", "every", "'Chairs' is plural countable, so 'a few' fits."),
    q("Identify the adjective of quality in: 'A gentle breeze cooled the classroom.'", "gentle", "breeze", "cooled", "classroom", "'Gentle' describes the quality of the noun 'breeze'."),
    q("Choose the proper adjective in: 'They enjoyed traditional Sri Lankan cuisine.'", "Sri Lankan", "enjoyed", "cuisine", "they", "'Sri Lankan' is formed from a proper noun and describes 'cuisine'."),
    q("Select the correct adjective order: 'She bought a ___ handbag.'", "small black leather", "leather black small", "black leather small", "small leather black", "Standard order is Size -> Colour -> Material ('small black leather')."),
    q("Arrange the adjectives properly: 'We stayed in an ___ cottage.'", "old wooden mountain", "wooden old mountain", "mountain wooden old", "old mountain wooden", "Order is Age -> Material -> Purpose/Noun-adj ('old wooden mountain')."),
    q("Choose the correct order: 'He wore a ___ shirt for the prize giving.'", "smart white cotton", "cotton white smart", "white cotton smart", "smart cotton white", "Order is Opinion -> Colour -> Material ('smart white cotton')."),
    q("Select the right participle adjective: 'The students found the documentary very ___.'", "interesting", "interested", "interest", "interests", "'-ing' adjectives describe the thing causing the feeling."),
    q("Choose the accurate form: 'Everyone was ___ by the magician's final trick.'", "amazed", "amazing", "amaze", "amazement", "'-ed' adjectives describe how people feel."),
    q("Fill in the blank: 'After walking ten kilometres, the hikers felt ___.'", "exhausted", "exhausting", "exhaust", "exhausts", "People experience the feeling, so use '-ed' ('exhausted')."),
    q("Select the right adjective: 'The math problem looked ___ at first glance.'", "confusing", "confused", "confuse", "confusion", "The problem causes confusion, so use 'confusing'."),
    q("Choose the correct comparative: 'Anuradhapura is ___ than many modern cities.'", "older", "oldest", "more old", "most old", "Short one-syllable adjectives add '-er' before 'than'."),
    q("Fill in the blank: 'Gold is much ___ than silver or copper.'", "more expensive", "expensiver", "most expensive", "more expensiver", "Multi-syllable adjectives use 'more' in the comparative."),
    q("Select the superlative form: 'Pidurutalagala is the ___ mountain in Sri Lanka.'", "highest", "higher", "most high", "more high", "Use 'the + superlative (-est)' for one-syllable adjectives."),
    q("Choose the irregular comparative: 'Your handwriting is ___ today than yesterday.'", "better", "gooder", "more good", "best", "'Good' has the irregular comparative 'better'."),
    q("Select the irregular superlative: 'That was the ___ storm in twenty years.'", "worst", "baddest", "most bad", "worse", "'Bad' forms the irregular superlative 'worst'."),
    q("Fill in the blank: 'Polonnaruwa is ___ from Colombo than Kurunegala.'", "farther", "more far", "farthest", "farer", "'Far' takes 'farther' (or 'further') before 'than'."),
    q("Choose the equal comparison: 'Kasun runs as ___ as his elder brother.'", "fast", "faster", "fastest", "more fast", "'As + base adjective/adverb + as' expresses equality."),
    q("Complete the comparison: 'This bag is not so ___ as the blue suitcase.'", "heavy", "heavier", "heaviest", "heavily", "'Not so/as + positive degree + as' uses the base adjective 'heavy'."),
    q("Select the right form: 'Health is far ___ important than material wealth.'", "more", "most", "much", "very", "Use 'more' before 'important' with 'than'."),
    q("Choose the accurate phrase: 'Of the two sisters, Tharushi is the ___.'", "taller", "tallest", "tall", "most tall", "When comparing exactly two items, use 'the + comparative'."),
    q("Select the right option: 'Mount Fuji is one of the ___ peaks in Asia.'", "most famous", "more famous", "famous", "famouser", "'One of the + superlative + plural noun' takes 'most famous'."),
    q("Identify the adverb of frequency in: 'He seldom arrives late for school.'", "seldom", "arrives", "late", "school", "'Seldom' indicates how often an action occurs."),
    q("Choose the correct placement: 'My grandmother ___ drinks herbal tea.'", "always", "never not", "everyday", "almost no", "Single-word frequency adverbs go before main verbs."),
    q("Select the natural position: 'They are ___ ready for the science quiz.'", "already", "yet", "still not yet", "ever", "Adverbs like 'already' follow the verb 'to be' ('are already')."),
    q("Fill in the blank: 'The train hasn't arrived at the platform ___.'", "yet", "already", "still", "just", "'Yet' is placed at the end of negative sentences and questions."),
    q("Choose the adverb of degree: 'The hall was ___ crowded for us to enter.'", "too", "very", "enough", "quite", "'Too + adjective + to-infinitive' expresses excess."),
    q("Select the right position for 'enough': 'Is the classroom ___ for forty desks?'", "large enough", "enough large", "very enough", "too enough", "'Enough' always follows the adjective or adverb it modifies."),
    q("Choose the right form: 'She spoke ___ so that the whole class could hear.'", "clearly", "clear", "clearness", "clearing", "Modify the verb 'spoke' with the adverb of manner 'clearly'."),
    q("Fill in the blank: 'Please drive ___ along the narrow mountain road.'", "carefully", "careful", "careless", "caring", "Use adverb 'carefully' to describe how to drive."),
    q("Select the adverb of manner: 'The old man walked ___ down the stairs.'", "slowly", "slow", "slowness", "slower", "Adverb 'slowly' modifies the verb 'walked'."),
    q("Choose the irregular adverb: 'Did you sleep ___ after the long journey?'", "well", "good", "nice", "sound", "'Well' is the adverb modifying 'sleep'."),
    q("Fill in the blank: 'Although he worked ___, he found the puzzle tricky.'", "hard", "hardly", "hardness", "harder than", "'Work hard' means work diligently; 'hardly' means scarcely."),
    q("Select the accurate adverb: 'There was ___ any rain during the dry season.'", "hardly", "hard", "heavy", "heavily", "'Hardly any' means almost none."),
    q("Choose the right word: 'We haven't met our cousin ___ at the exhibition.'", "lately", "late", "latest", "latter", "'Lately' means recently (common with Present Perfect)."),
    q("Fill in the blank: 'Nimal arrived ___ for assembly because of heavy traffic.'", "late", "lately", "later", "latter", "'Late' means behind schedule; 'lately' means recently."),
    q("Select the accurate option: 'The bird flew ___ above the coconut palms.'", "high", "highly", "height", "highness", "'High' denotes physical altitude; 'highly' means greatly."),
    q("Choose the right adverb: 'Mrs. Perera is ___ respected by all her students.'", "highly", "high", "height", "higher", "'Highly' modifies past participles like 'respected' to mean very much."),
    q("Identify the adverb of place in: 'Leave your muddy shoes outside.'", "outside", "muddy", "shoes", "leave", "'Outside' answers the question 'Where?'."),
    q("Select the adverb of time in: 'We will submit the group report tomorrow.'", "tomorrow", "group", "submit", "report", "'Tomorrow' answers the question 'When?'."),
    q("Choose the right intensifier: 'This tea is ___ hot to drink right now.'", "too", "enough", "much", "so much", "'Too hot to drink' conveys excessive heat preventing action."),
    q("Fill in the blank: 'The parcel was ___ heavy that two boys had to carry it.'", "so", "too", "very", "such", "'So + adjective + that' introduces a result clause."),
    q("Select the accurate word: 'It was ___ a pleasant evening that nobody left early.'", "such", "so", "too", "very", "'Such + a/an + adjective + noun + that' is the required structure."),
    q("Choose the right word: 'There were ___ many spectators that the gate closed.'", "so", "such", "very", "too", "Before 'many/much/few/little', use 'so' rather than 'such'."),
    q("Fill in the blank: 'I ___ agree with the point raised by the first speaker.'", "completely", "complete", "completion", "completed", "Modify the verb 'agree' with the adverb 'completely'."),
    q("Select the right comparative adverb: 'She sings ___ than anyone in the choir.'", "more sweetly", "sweetlier", "most sweetly", "sweeter", "Adverbs ending in -ly form comparatives with 'more'."),
    q("Choose the comparative adverb: 'Which athlete jumped ___ in the final round?'", "farthest", "farther", "more far", "farer", "Superlative across multiple athletes uses 'farthest'."),
    q("Fill in the blank: 'Among all the cars, the red one arrived ___.'", "earliest", "earlier", "more early", "most early", "Single-word adverb 'early' takes '-est' in the superlative."),
    q("Select the accurate option: 'Please behave ___ while the guests are speaking.'", "politely", "polite", "politeness", "impolite", "Modify 'behave' with the adverb of manner 'politely'."),
    q("Choose the right word: 'This fabric feels ___ and soft to the touch.'", "smooth", "smoothly", "smoothness", "smoothing", "Sensory verb 'feels' takes an adjective: 'smooth'."),
    q("Fill in the blank: 'The sky suddenly grew ___ before the afternoon thunderstorm.'", "dark", "darkly", "darkness", "darken", "Change-of-state linking verb 'grew' takes the adjective 'dark'."),
    q("Select the accurate option: 'Keep ___ during the silent reading session.'", "quiet", "quietly", "quietness", "quite", "'Keep + adjective' means remain in that state ('keep quiet')."),
    q("Choose the right word: 'The old clock is ___ accurate despite its age.'", "quite", "quiet", "quietly", "quitter", "'Quite' is an adverb meaning fairly/completely; 'quiet' means silent."),
    q("Fill in the blank: 'Almost ___ student in Grade 11 passed the mock test.'", "every", "all", "each of", "most", "'Almost every + singular noun' is grammatically accurate."),
    q("Select the accurate determiner: '___ of the players wore the new blue jersey.'", "Most", "Every", "Each a", "Whole", "'Most of the + plural noun' pairs with plural 'players'."),
    q("Choose the right determiner: 'She spent the ___ afternoon revising past papers.'", "whole", "all", "every", "both", "'The whole + singular noun' precedes nouns like 'afternoon'."),
    q("Fill in the blank: '___ the guests enjoyed the traditional welcome dance.'", "All", "Every", "Each", "Whole", "'All the + plural noun' takes 'All' before 'the guests'."),
    q("Select the correct determiner: '___ of my two cousins live in Kandy.'", "Both", "Each", "Either", "Every", "Plural verb 'live' requires plural 'Both'."),
    q("Choose the right word: 'There is ___ difference between these two dictionaries.'", "no", "not", "none", "never", "'No' directly modifies the noun 'difference'."),
    q("Fill in the blank: 'I asked for blank sheets, but there were ___ left.'", "none", "no", "not", "neither", "'None' stands alone as a pronoun at the end of the clause."),
    q("Select the right adjective: 'The village folk are famous for their ___ welcome.'", "warm", "warmly", "warmth", "warmed", "Modify the noun 'welcome' with the adjective 'warm'."),
    q("Choose the accurate form: 'Have you seen ___ interesting exhibits at the museum?'", "any", "a", "an", "much", "Plural noun 'exhibits' in a question pairs with 'any'."),
    q("Fill in the blank: 'He gave me ___ useful piece of advice before the exam.'", "a", "an", "many", "few", "'Useful' begins with a /j/ sound ('yoo'), so use 'a useful piece'.")
  )
}
